makeMtLab(document.getElementById("lab-l16"),{id:"l16",scenarios:[{"label": "Ví dụ: P khi đổi sản phẩm giữa ca", "note": "Cộng thời gian lý tưởng theo từng sản phẩm.", "steps": [{"t": "Hai sản phẩm", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Sản phẩm<\/th><th scope=\"col\">Số đếm<\/th><th scope=\"col\">Chu kỳ<\/th><\/tr><\/thead><tbody><tr><td>SP-07<\/td><td>6 000<\/td><td>2,0 s<\/td><\/tr><tr><td>SP-08<\/td><td>3 000<\/td><td>2,4 s<\/td><\/tr><\/tbody><\/table>"}, {"t": "Thời gian lý tưởng", "html": "<p class=\"mt-calc\">12 000 + 7 200 = 19 200 s<\/p>"}, {"t": "P", "html": "<p class=\"mt-calc\">19 200 / 21 600 ≈ <b>0,8889<\/b><\/p>", "ask": {"q": "P bằng bao nhiêu?", "o": ["0,8889", "0,8333", "1,0000"], "a": 0}}]}, {"label": "Ví dụ: Gộp OEE hai máy", "note": "Trọng số theo thời gian kế hoạch.", "steps": [{"t": "M1: 0,80 (450 phút), M4: 0,60 (225 phút)", "html": "<p class=\"mt-calc\">Trung bình cộng = 0,70<\/p>"}, {"t": "Gộp đúng", "html": "<p class=\"mt-calc\">(360 + 135) / 675 ≈ <b>0,7333<\/b><\/p>", "ask": {"q": "OEE gộp đúng?", "o": ["0,70", "0,7333", "0,6667"], "a": 1}}]}, {"label": "Bẫy: Một chu kỳ cho hai sản phẩm", "note": "Dùng 2,0 s cho cả SP-08.", "steps": [{"t": "P sai", "html": "<p class=\"mt-calc\">2,0 × 9 000 / 21 600 ≈ 0,8333<\/p>"}, {"t": "So với đúng 0,8889", "html": "<p class=\"mt-calc\">P bị kéo xuống vì SP-08 vốn chậm hơn<\/p>", "say": "<p>Mỗi sản phẩm một chu kỳ lý tưởng.<\/p>"}]}, {"label": "Bẫy: Dừng ngắn biến mất", "note": "Đọc mỗi 10 s, dừng 6 s.", "steps": [{"t": "Đọc lúc 09:00:00 và 09:00:10", "html": "<p class=\"mt-calc\">Cả hai lần đều RUN<\/p>"}, {"t": "Máy dừng 09:00:02–09:00:08", "html": "<p class=\"mt-calc\">Không có sự kiện nào được ghi<\/p>", "ask": {"q": "Thông tin nào vẫn còn?", "o": ["Thời điểm dừng", "Số đếm sản phẩm (PLC cộng dồn)"], "a": 1}}]}, {"label": "Lỗi: Trung bình cộng OEE các ca", "note": "Ca ngắn có trọng số như ca dài.", "steps": [{"t": "Ca 1: 0,80 (450 phút); ca tăng cường: 0,40 (60 phút)", "html": "<p class=\"mt-calc\">Trung bình cộng = 0,60<\/p>"}, {"t": "Gộp đúng", "html": "<p class=\"mt-calc\">(360 + 24) / 510 ≈ 0,7529<\/p>", "say": "<p>Trung bình cộng làm ca 60 phút kéo OEE ngày xuống sai.<\/p>"}]}]});
